const CHECKOUT_SESSIONS: &str = "/api/marketplace/account/checkout-sessions/";

/// A buy checkout's reads and writes, as the stand-in answers them. `chk_gone` is not found,
/// `chk_theirs` is another account's, `chk_down` fails and `chk_slow` has not caught up with
/// any write; `chk_offer` is a purchase intent and `chk_paid`'s payment has started. Each review
/// write applies with a receipt (an address in 00000 is one the API cannot deliver to); Pay now
/// starts `pay_1`, but `chk_stale`'s quote is stale, and `chk_offer`'s Submit offer becomes the
/// offer `ofr_1` (`chk_offered` already did). Payments quotes $620.00 as the sandbox
/// does; the wallet holds $25.00. `pay_1`'s summary is $638.83 ready for payment; `pay_down`'s
/// read fails (`chk_paydown` started it). `chk_lostpay`'s Pay now starts `pay_1` and its answer is
/// lost, `chk_unsure`'s is lost and starts nothing, and `chk_moved`'s is refused as already
/// started with other details.
fn checkout_sessions(stand: &Stand, method: &Method, uri: &Uri, headers: &HeaderMap, body: &str) -> Option<Response> {
    let path = uri.path();
    if path == "/api/settlement/wallet" {
        return Some(Json(json!({ "available_balance_amount": "25.00", "currency_code": "USD" })).into_response());
    }
    if path == "/api/marketplace/account/sell-list/ship-from-addresses" && *method == Method::GET {
        return Some(
            Json(json!({ "items": [{
            "shipping_address_id": "adr_home", "account_id": "acc_buyer", "label": "Home", "recipient_name": "Demo Collector",
            "company": null, "line1": "42 Binder Lane", "line2": null, "city": "Evanston", "state": "IL", "postal_code": "60201",
            "country": "US", "phone": null, "email": "collector@chasesets.test", "is_default": true,
            "updated_at": "2026-10-27 06:26:37.701+00",
        }] }))
            .into_response(),
        );
    }
    if let Some(payment) = path.strip_prefix("/api/marketplace/account/checkout-payment-summaries/") {
        return Some(match payment {
            "pay_1" => Json(json!({
                "payment_id": "pay_1", "amount": "638.83", "currency_code": "usd", "status": "pending-confirmation",
            }))
            .into_response(),
            "pay_down" => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
            _ => refusal(StatusCode::NOT_FOUND, "not_found", "Payment summary not found."),
        });
    }
    if path == "/api/marketplace/account/checkout-payment-affordances" {
        return Some(Json(json!({ "items": [] })).into_response());
    }
    if path == "/api/marketplace/account/checkout/preview-status" {
        let query: HashMap<String, String> = uri
            .query()
            .unwrap_or_default()
            .split('&')
            .filter_map(|p| p.split_once('='))
            .map(|(k, v)| (k.to_owned(), v.to_owned()))
            .collect();
        let quote = |category: &str, fee: &str, total: &str| {
            json!({
                "payment_method_category": category, "marketplace_checkout_fee_amount": fee, "total_amount": total,
                "quote_fingerprint": format!("fq_{category}"),
            })
        };
        let quotes = [
            quote("card", "18.83", "638.83"),
            quote("bank-account", "3.12", "623.12"),
            quote("platform-credit", "0.00", "620.00"),
        ];
        let asked = query.get("paymentMethodCategory").cloned().unwrap_or_default();
        let chosen =
            quotes.iter().find(|q| q["payment_method_category"] == asked.as_str()).cloned().unwrap_or_else(|| quotes[0].clone());
        let credit = query.get("requestedBalanceCreditAmount").cloned().unwrap_or_default();
        return Some(
            Json(json!({
                "marketplace_checkout_fee": chosen, "payment_method_quotes": quotes,
                "wallet_credit": { "requested_amount": credit, "applied_amount": "0.00" },
            }))
            .into_response(),
        );
    }
    let rest = path.strip_prefix(CHECKOUT_SESSIONS)?;
    let (id, write) = rest.split_once('/').unwrap_or((rest, ""));
    if *method == Method::GET && write.is_empty() {
        return Some(match id {
            "chk_gone" => refusal(StatusCode::NOT_FOUND, "not_found", "Checkout session not found."),
            "chk_theirs" => refusal(StatusCode::FORBIDDEN, "forbidden", "This checkout belongs to another account."),
            "chk_down" => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
            "chk_slow" if waits_for(headers).is_some() => refusal(
                StatusCode::SERVICE_UNAVAILABLE,
                "projection_freshness_timeout",
                "Projection read model did not catch up to the requested write receipt before the freshness timeout.",
            ),
            _ => {
                let mut session = checkout_session(id);
                if stand.kept.lock().unwrap().contains_key(&format!("confirm:{id}")) {
                    session["payment_id"] = json!("pay_1");
                }
                Json(session).into_response()
            }
        });
    }
    if *method != Method::POST {
        return None;
    }
    Some(match write {
        "shipping-address" if body.contains(r#""postalCode":"00000""#) => {
            refusal(StatusCode::UNPROCESSABLE_ENTITY, "shipping_address_unsupported", "We cannot deliver to this address.")
        }
        "shipping-option" => committed(StatusCode::OK, "checkout", "11", json!({})),
        "shipping-address" => committed(StatusCode::OK, "checkout", "12", json!({})),
        // As Checkout refuses it for a purchase intent (chase-sets/chase-sets#10821).
        "authenticity-check-opt-in" if id == "chk_offer" => refusal(
            StatusCode::BAD_REQUEST,
            "validation_failed",
            "Purchase intent checkout does not offer the authenticity check.",
        ),
        "authenticity-check-opt-in" => committed(StatusCode::OK, "checkout", "13", json!({})),
        "fulfillment-preview" => committed(StatusCode::OK, "checkout", "14", json!({})),
        "confirm" if id == "chk_stale" => refusal(StatusCode::CONFLICT, "fee_quote_stale", "The checkout fee changed."),
        "confirm" if id == "chk_lostpay" => {
            stand.kept.lock().unwrap().insert(format!("confirm:{id}"), json!({}));
            StatusCode::GATEWAY_TIMEOUT.into_response()
        }
        "confirm" if id == "chk_unsure" => StatusCode::BAD_GATEWAY.into_response(),
        "confirm" if id == "chk_moved" => refusal(
            StatusCode::CONFLICT,
            "checkout_confirmation_changed",
            "This checkout already started with different order or payment details.",
        ),
        "confirm" if id == "chk_offer" => {
            committed(StatusCode::OK, "checkout", "16", json!({ "offer_id": "ofr_1", "status": "purchase-intent-submitted" }))
        }
        "confirm" => committed(StatusCode::OK, "checkout", "15", json!({ "payment_id": "pay_1" })),
        _ => return None,
    })
}

/// Attempt ids the payment methods stand-in answers by: Payments could not confirm it (503
/// `attempt_unconfirmed`), it is another attempt's (409 `attempt_conflict`), it was refused (400
/// `validation_failed`), or the session ended (401). Any other is applied.
const PM_UNCONFIRMED: &str = "00000000-0000-4000-8000-000000000503";
const PM_CONFLICT: &str = "00000000-0000-4000-8000-000000000409";
const PM_REFUSED: &str = "00000000-0000-4000-8000-000000000400";
const PM_REAUTH: &str = "00000000-0000-4000-8000-000000000401";
const PM_OK: &str = "3f2504e0-4f89-41d3-9a0c-0305e82c3301";

/// The account's saved payment methods, as Payments answers them: `spm_card` is the ready default,
/// `spm_bank` needs setup, `spm_gone` was removed (`card_none` has none). A setup starts as
/// `spr_1` with a SetupIntent's secret; `spr_saved` saved a card, `spr_wait` has not been told,
/// `spr_unknown` is not the account's and `spr_down` has no answer. A change to `spm_missing` is
/// not found; any change applied answers with a receipt at 61.
fn payment_methods(session: &str, method: &Method, path: &str, body: &str) -> Option<Response> {
    let rest = path.strip_prefix("/api/marketplace/account/payment-methods")?;
    let method_of = |id: &str, category: &str, readiness: &str, default: bool| {
        json!({
            "instrument_id": id, "account_id": "acc_seller", "payment_method_category": category,
            "provider": "stripe", "display_label": format!("Synthetic {id}"), "confirmation_experience": "embedded",
            "readiness": readiness, "is_default": default, "created_at": "2026-10-20T15:00:00.000Z",
            "updated_at": "2026-10-28T13:05:00.000Z", "allow_redisplay": "always", "consent_id": null, "removed_at": null,
        })
    };
    let refused =
        |status: StatusCode, code: &str| (status, Json(json!({ "error": { "code": code, "message": code } }))).into_response();
    if *method == Method::GET && rest.is_empty() {
        let items = if session == "card_none" {
            Vec::new()
        } else {
            vec![
                method_of("spm_card", "card", "ready", true),
                method_of("spm_bank", "bank-account", "setup-required", false),
                method_of("spm_gone", "card", "removed", false),
            ]
        };
        return Some(Json(json!({ "items": items })).into_response());
    }
    if *method != Method::POST {
        return None;
    }
    if rest == "/reconcile" {
        return Some(Json(json!({ "checked": 3, "updated": 0, "removed": 0, "items": [] })).into_response());
    }
    if let Some(setup) = rest.strip_prefix("/setup-sessions/").and_then(|r| r.strip_suffix("/reconcile")) {
        return Some(match setup {
            "spr_saved" => Json(json!({ "instrument": method_of("spm_new", "card", "ready", false) })).into_response(),
            "spr_wait" => Json(json!({ "instrument": null })).into_response(),
            "spr_down" => StatusCode::BAD_GATEWAY.into_response(),
            _ => refused(StatusCode::BAD_REQUEST, "validation_failed"),
        });
    }
    let sent: Value = serde_json::from_str(body).unwrap_or_default();
    if sent["accountId"] != "acc_seller" {
        return Some(refused(StatusCode::CONFLICT, "account_changed"));
    }
    match sent["attemptId"].as_str().unwrap_or_default() {
        PM_UNCONFIRMED => return Some(refused(StatusCode::SERVICE_UNAVAILABLE, "attempt_unconfirmed")),
        PM_CONFLICT => return Some(refused(StatusCode::CONFLICT, "attempt_conflict")),
        PM_REFUSED => return Some(refused(StatusCode::BAD_REQUEST, "validation_failed")),
        PM_REAUTH => return Some(StatusCode::UNAUTHORIZED.into_response()),
        _ => {}
    }
    if rest == "/setup-sessions" {
        let setup = json!({
            "setup_reference_id": "spr_1", "processor_setup_reference": "seti_1", "processor_client_secret": "seti_1_secret_x",
            "processor_redirect_url": null, "processor_status": "requires_payment_method", "processor_publishable_key": "pk_stand_in_1",
        });
        return Some((StatusCode::CREATED, Json(setup)).into_response());
    }
    let (id, verb) = rest.strip_prefix('/')?.split_once('/')?;
    if !matches!(verb, "default" | "remove") {
        return None;
    }
    if id == "spm_missing" {
        return Some(refused(StatusCode::NOT_FOUND, "not_found"));
    }
    Some(committed(StatusCode::OK, "payments", "61", method_of(id, "card", "ready", verb == "default")))
}

/// A buyer's payments, as Payments answers them. `pay_1` waits for the buyer with a Payment
/// Intent's secret, `pay_cs` with a Checkout Session's; `pay_paid` is captured, `pay_failed`
/// was declined, `pay_noemail`'s order has no email, `pay_slow` has not caught up with any
/// write and `pay_broken` fails. Any other is not the account's. The orders: `ord_pay` ships to
/// the checkout's address and is due 2026-10-29 and carries the seller's evidence, `ord_noemail` has
/// no email, and `ord_gone` is not the account's. Payments quotes the card and a bank account, and
/// refuses a wallet credit of $999.00 and withholds $25.00 until the terms are accepted; starting a
/// payment (Continue to payment) starts `pay_new`.
fn account_payments(method: &Method, uri: &Uri, headers: &HeaderMap, body: &str) -> Option<Response> {
    if *method == Method::POST && uri.path() == "/api/marketplace/account/payments" {
        let sent: Value = serde_json::from_str(body).unwrap_or_default();
        if sent["orderIds"] == json!(["ord_refused"]) {
            return Some(refusal(StatusCode::CONFLICT, "payment_quote_stale", "The payment quote changed. Review it again."));
        }
        let receipt = percent_encoding::utf8_percent_encode(RECEIPT, percent_encoding::NON_ALPHANUMERIC).to_string();
        let headers = [("chase-sets-commit-position", "42".to_owned()), ("chase-sets-commit-receipt", receipt)];
        return Some(
            (StatusCode::CREATED, headers, Json(json!({ "payment_id": "pay_new", "status": "pending-confirmation" })))
                .into_response(),
        );
    }
    // Retry payment: a new payment for the orders, at the quote Payments gives for them again.
    if *method == Method::POST && uri.path() == "/api/marketplace/account/checkout/recover" {
        let receipt = percent_encoding::utf8_percent_encode(RECEIPT, percent_encoding::NON_ALPHANUMERIC).to_string();
        let headers = [("chase-sets-commit-position", "42".to_owned()), ("chase-sets-commit-receipt", receipt)];
        return Some(
            (StatusCode::CREATED, headers, Json(json!({ "payment_id": "pay_retry", "status": "pending-confirmation" })))
                .into_response(),
        );
    }
    if *method != Method::GET {
        return None;
    }
    if uri.path() == "/api/marketplace/account/checkout/status" {
        if uri.query().unwrap_or_default().contains("requestedBalanceCreditAmount=999.00") {
            return Some(refusal(
                StatusCode::BAD_REQUEST,
                "validation_failed",
                "Requested balance credit exceeds the available wallet balance.",
            ));
        }
        let quote = json!({
            "payment_method_category": "card", "marketplace_checkout_fee_amount": "18.83",
            "marketplace_checkout_fee_reduction_amount": "0.00", "total_amount": "638.83",
            "processor_amount": "613.83", "quote_fingerprint": "fp-retry",
        });
        let bank = json!({
            "payment_method_category": "bank-account", "marketplace_checkout_fee_amount": "6.20",
            "marketplace_checkout_fee_reduction_amount": "12.63", "total_amount": "626.20",
            "processor_amount": "601.20", "quote_fingerprint": "fp-bank",
        });
        // The wallet's $25.00 is withheld until the buyer accepts the current terms, as Settlement does.
        let reasons = if uri.query().unwrap_or_default().contains("requestedBalanceCreditAmount=25.00") {
            json!([{
                "code": "wallet-terms-not-accepted",
                "message": "Accept the current Terms of Service to use wallet balance as payment.",
            }])
        } else {
            json!([])
        };
        return Some(
            Json(json!({
                "marketplace_checkout_fee": quote, "payment_method_quotes": [quote, bank],
                "unavailable_reason_details": reasons,
            }))
            .into_response(),
        );
    }
    if uri.path() == "/api/marketplace/account/order-inputs" {
        let asked = uri.query().unwrap_or_default();
        if asked.contains("ord_gone") {
            return Some(refusal(StatusCode::NOT_FOUND, "not_found", "Order ord_gone was not found."));
        }
        let order = |id: &str, email: Option<&str>| {
            json!({
                "order_id": id, "buyer_account_id": "acc_seller", "buyer_email": email,
                "shipping_destination_snapshot": {
                    "name": "Demo Collector", "line1": "42 Binder Lane", "line2": null, "city": "Evanston",
                    "state": "IL", "postalCode": "60201", "country": "US", "email": null,
                },
                "total_amount": "638.83", "marketplace_sales_fee_amount": "31.00",
                "seller_payout_amount": "589.00", "sales_tax_amount": "0.00", "status": "pending-payment",
                "payment_deadline_at": "2026-10-29T17:00:00.000Z",
                "listing_evidence": if email.is_some() { json!([{
                    "line_id": "line_1", "item_title": "Charizard Base Set",
                    "gallery": [{ "photoId": "ph_1", "altText": null, "assets": [
                        { "role": "thumbnail", "publicUrl": "https://img.test/ph_1-t.webp", "width": 120, "height": 160, "density": 1 },
                        { "role": "catalog-detail", "publicUrl": "https://img.test/ph_1-d.webp", "width": 600, "height": 800, "density": 1 },
                    ] }],
                }]) } else { json!([]) },
            })
        };
        let mut orders = Vec::new();
        if asked.contains("ord_pay") {
            orders.push(order("ord_pay", Some("collector@chasesets.test")));
        }
        if asked.contains("ord_noemail") {
            orders.push(order("ord_noemail", None));
        }
        return Some(Json(json!({ "orders": orders })).into_response());
    }
    let id = uri.path().strip_prefix("/api/marketplace/account/payments/")?;
    let mut payment = json!({
        "payment_id": id, "buyer_account_id": "acc_seller", "order_ids": ["ord_pay"], "amount": "638.83",
        "balance_credit_amount": "25.00", "processor_amount": "613.83", "marketplace_checkout_fee_amount": "18.83",
        "payment_method_category": "card", "currency_code": "usd", "processor_name": "stripe",
        "processor_payment_reference": "pi_1", "processor_client_secret": "pi_1_secret_abc",
        "processor_redirect_url": null, "processor_status": "requires_payment_method",
        "processor_publishable_key": "pk_stand_in_1", "source_context": "checkout", "source_reference_id": "chk_paid",
        "status": "pending-confirmation", "failure_code": null, "failure_message": null,
        "created_at": "2026-10-28T17:00:00.000Z", "updated_at": "2026-10-28T17:00:00.000Z",
        "captured_at": null, "failed_at": null, "cancelled_at": null, "provider_events": [],
    });
    match id {
        "pay_1" => {}
        "pay_cs" => payment["processor_client_secret"] = json!("cs_test_1_secret"),
        "pay_noemail" => payment["order_ids"] = json!(["ord_noemail"]),
        "pay_paid" => {
            payment["status"] = json!("captured");
            payment["processor_status"] = json!("succeeded");
            payment["processor_client_secret"] = json!(null);
            payment["captured_at"] = json!("2026-10-28T17:05:00.000Z");
            payment["provider_events"] = json!([{
                "provider_event_id": "evt_1", "provider_name": "stripe", "event_kind": "payment-captured",
                "provider_object_reference": "pi_1", "received_at": "2026-10-28T17:05:00.000Z",
            }]);
        }
        "pay_failed" => {
            payment["status"] = json!("failed");
            payment["failure_code"] = json!("card_declined");
            payment["failure_message"] = json!("Your card was declined.");
            payment["failed_at"] = json!("2026-10-28T17:05:00.000Z");
        }
        "pay_slow" if waits_for(headers).is_some() => {
            return Some(refusal(
                StatusCode::SERVICE_UNAVAILABLE,
                "projection_freshness_timeout",
                "Projection read model did not catch up to the requested write receipt before the freshness timeout.",
            ));
        }
        "pay_broken" => return Some(StatusCode::INTERNAL_SERVER_ERROR.into_response()),
        // A guest's payment its guest checkout no longer reaches.
        "pay_gone" => return Some(refusal(StatusCode::FORBIDDEN, "forbidden", "Forbidden.")),
        _ => return Some(refusal(StatusCode::NOT_FOUND, "not_found", "Payment not found.")),
    }
    Some(Json(payment).into_response())
}

const CART_COMMANDS: &str = "/api/marketplace/account/cart/commands";
const GUEST_CART_COMMANDS: &str = "/api/marketplace/guest/cart/commands";
const CART_ATTEMPTS: &str = "/api/marketplace/account/command-attempts/";

/// Cart writes, as the stand-in answers them. A command's line says what happens: `cli_gone` is
/// no longer in the cart (its command is a conflict, the others apply), `cli_refused` is refused
/// with nothing applied, `cli_lost` applies and its answer is lost, `cli_unknown`'s answer is lost
/// and nothing is kept. Any other applies, at position 11. `stale`'s session has ended. A lookup
/// answers what was kept. A guest cart's commands need the guest cart they are for.
fn cart_commands(stand: &Stand, session: &str, method: &Method, path: &str, headers: &HeaderMap, body: &str) -> Option<Response> {
    if let Some(id) = path.strip_prefix(CART_ATTEMPTS) {
        return Some(match stand.kept.lock().unwrap().get(id) {
            Some(attempt) => Json(json!({ "attempt": attempt })).into_response(),
            None => refusal(StatusCode::NOT_FOUND, "command_attempt_not_found", "Command attempt not found."),
        });
    }
    if (path != CART_COMMANDS && path != GUEST_CART_COMMANDS) || *method != Method::POST {
        return None;
    }
    if path == GUEST_CART_COMMANDS && !headers.contains_key("x-checkout-anonymous-cart-id") {
        return Some(refusal(StatusCode::BAD_REQUEST, "anonymous_cart_required", "A guest cart is required."));
    }
    if path == CART_COMMANDS && session == "stale" {
        return Some(refusal(StatusCode::UNAUTHORIZED, "unauthenticated", "Sign in."));
    }
    let sent: Value = serde_json::from_str(body).unwrap_or_default();
    let attempt = sent["attemptId"].as_str().unwrap_or_default().to_owned();
    let lines: Vec<String> =
        sent["commands"].as_array().into_iter().flatten().map(|c| c["lineId"].as_str().unwrap_or_default().to_owned()).collect();
    let has = |id: &str| lines.iter().any(|l| l == id);
    if has("cli_refused") {
        return Some(refusal(StatusCode::UNPROCESSABLE_ENTITY, "validation_failed", "Only 2 are available."));
    }
    if has("cli_unknown") {
        return Some(StatusCode::SERVICE_UNAVAILABLE.into_response());
    }
    let vector: Vec<Value> = lines
        .iter()
        .map(|line| match line.as_str() {
            "cli_gone" => json!({ "lineId": line, "outcome": "conflict", "message": "Cart line not found." }),
            _ => json!({ "lineId": line, "outcome": "succeeded", "message": null }),
        })
        .collect();
    let kept = json!({
        "ownerStatus": "committed", "vector": vector, "commitReceipt": { "eventId": "evt_cart", "globalPosition": "11" },
    });
    stand.kept.lock().unwrap().insert(attempt, kept.clone());
    if has("cli_lost") {
        return Some(StatusCode::BAD_GATEWAY.into_response());
    }
    let receipt = r#"[{"sourceContextName":"checkout","maxGlobalPosition":"11","eventIds":["evt_cart"]}]"#;
    let receipt = percent_encoding::utf8_percent_encode(receipt, percent_encoding::NON_ALPHANUMERIC).to_string();
    let headers = [("chase-sets-commit-position", "11".to_owned()), ("chase-sets-commit-receipt", receipt)];
    Some((StatusCode::OK, headers, Json(json!({ "attempt": kept }))).into_response())
}

const ACCOUNT_CART_ADD: &str = "/api/marketplace/account/cart";
const GUEST_CART_ADD: &str = "/api/marketplace/guest/cart";
const GUEST_ATTEMPTS: &str = "/api/marketplace/guest/command-attempts/";

/// An item page's cart add, as the stand-in answers it, to the account's cart or (with its id) a
/// guest's. The quantity says what happens: 7 is refused with nothing applied, 8 applies and its
/// answer is lost, 9's answer is lost and nothing is kept; any other applies, at position 12. A
/// guest's lookup answers what was kept.
fn cart_add(stand: &Stand, method: &Method, path: &str, headers: &HeaderMap, body: &str) -> Option<Response> {
    let guest = headers.get("x-checkout-anonymous-cart-id").and_then(|v| v.to_str().ok()).filter(|id| id.starts_with("anon_"));
    if let Some(id) = path.strip_prefix(GUEST_ATTEMPTS) {
        return Some(match (guest, stand.kept.lock().unwrap().get(id)) {
            (None, _) => refusal(StatusCode::BAD_REQUEST, "anonymous_cart_required", "Sign in."),
            (Some(_), Some(attempt)) => Json(json!({ "attempt": attempt })).into_response(),
            (Some(_), None) => refusal(StatusCode::NOT_FOUND, "command_attempt_not_found", "Command attempt not found."),
        });
    }
    if *method != Method::POST || (path != ACCOUNT_CART_ADD && path != GUEST_CART_ADD) {
        return None;
    }
    if path == GUEST_CART_ADD && guest.is_none() {
        return Some(refusal(StatusCode::BAD_REQUEST, "anonymous_cart_required", "A guest cart is required."));
    }
    let sent: Value = serde_json::from_str(body).unwrap_or_default();
    let attempt = sent["attemptId"].as_str().unwrap_or_default().to_owned();
    match sent["quantity"].as_u64() {
        Some(7) => return Some(refusal(StatusCode::BAD_REQUEST, "validation_failed", "Only 2 are available.")),
        Some(9) => return Some(StatusCode::SERVICE_UNAVAILABLE.into_response()),
        _ => {}
    }
    let kept = json!({
        "ownerStatus": "committed",
        "vector": [{ "lineId": "cli_new", "outcome": "succeeded", "message": null }],
        "commitReceipt": { "eventId": "evt_add", "globalPosition": "12" },
    });
    stand.kept.lock().unwrap().insert(attempt, kept.clone());
    if sent["quantity"].as_u64() == Some(8) {
        return Some(StatusCode::BAD_GATEWAY.into_response());
    }
    let receipt = r#"[{"sourceContextName":"checkout","maxGlobalPosition":"12","eventIds":["evt_add"]}]"#;
    let receipt = percent_encoding::utf8_percent_encode(receipt, percent_encoding::NON_ALPHANUMERIC).to_string();
    let headers = [("chase-sets-commit-position", "12".to_owned()), ("chase-sets-commit-receipt", receipt)];
    let answer = json!({ "id": "cli_new", "version": 1, "status": "added", "attempt": kept });
    Some((StatusCode::CREATED, headers, Json(answer)).into_response())
}

const ACCOUNT_SELL_LIST: &str = "/api/marketplace/account/sell-list";
const GUEST_SELL_LIST: &str = "/api/marketplace/guest/sell-list";
const STANDARD_TERMS: &str = "/api/marketplace/terms/public-standard/listing-preview";

/// A sell-list add and the public standard terms, as the stand-in answers them. An offer's line
/// is refused as the API refuses one without a listing (chase-sets/chase-sets#8830); a product's
/// is added at position 13. The terms are a 5% fee and a 5% shipping allowance.
fn sell_list(method: &Method, path: &str, headers: &HeaderMap, body: &str) -> Option<Response> {
    if *method != Method::POST {
        return None;
    }
    let sent: Value = serde_json::from_str(body).unwrap_or_default();
    if path == STANDARD_TERMS {
        let cents = platform::money::cents(sent["priceAmount"].as_str().unwrap_or_default()).unwrap_or_default();
        let amount = |c: i64| format!("{}.{:02}", c / 100, c % 100);
        return Some(
            Json(json!({
                "marketplace_sales_fee_unit_amount": amount(cents / 20), "seller_net_unit_amount": amount(cents - cents / 20),
                "shipping_allowance_percentage_bps": 500, "source_label": "Standard seller terms",
                "resolved_at": "2026-10-25T19:25:20.646Z",
            }))
            .into_response(),
        );
    }
    if path != ACCOUNT_SELL_LIST && path != GUEST_SELL_LIST {
        return None;
    }
    let guest =
        headers.get("x-checkout-anonymous-sell-list-id").and_then(|v| v.to_str().ok()).filter(|id| id.starts_with("anon_"));
    if path == GUEST_SELL_LIST && guest.is_none() {
        return Some(refusal(StatusCode::BAD_REQUEST, "anonymous_sell_list_required", "Sign in."));
    }
    if sent["lineType"] == "selected-offer" && sent["listingId"].is_null() {
        return Some(refusal(
            StatusCode::BAD_REQUEST,
            "validation_failed",
            "Selected offer sell-list lines must reference an Offer and exact Listing.",
        ));
    }
    let receipt = r#"[{"sourceContextName":"checkout","maxGlobalPosition":"13","eventIds":["evt_sell"]}]"#;
    let receipt = percent_encoding::utf8_percent_encode(receipt, percent_encoding::NON_ALPHANUMERIC).to_string();
    let headers = [("chase-sets-commit-position", "13".to_owned()), ("chase-sets-commit-receipt", receipt)];
    Some((StatusCode::CREATED, headers, Json(json!({ "id": "sll_new", "version": 1, "status": "added" }))).into_response())
}

/// A listing's evidence as the sell list reviews it: a front matched by `ph_front`, an unmatched
/// `ph_extra`, and a back that is matched only when `complete`.
fn sell_evidence(listing: &str, complete: bool) -> Value {
    let photo = |id: &str, view: Option<&str>| {
        json!({
            "photoId": id, "status": "active", "viewKind": view, "altText": null,
            "assetSet": { "source": { "role": "source", "publicUrl": format!("https://cdn.example/{id}.jpg") },
                "variants": [{ "role": "thumbnail", "publicUrl": format!("https://cdn.example/{id}_t.jpg") }] },
        })
    };
    json!({
        "listingId": listing,
        "evidence": [photo("ph_front", Some("front")), photo("ph_extra", None)],
        "requirements": { "requiredSlots": [{ "slotId": "front", "viewKind": "front" }, { "slotId": "back", "viewKind": "back" }] },
        "coverage": {
            "complete": complete, "unmetCodes": if complete { json!([]) } else { json!(["slot-missing"]) },
            "slots": [
                { "slotId": "front", "viewKind": "front", "satisfied": true, "unmetCode": null, "matchedPhotoId": "ph_front" },
                { "slotId": "back", "viewKind": "back", "satisfied": complete,
                  "unmetCode": if complete { Value::Null } else { json!("slot-missing") },
                  "matchedPhotoId": if complete { json!("ph_back") } else { Value::Null } },
            ],
            "activePhotoCount": 2, "minimumPhotoCount": 2,
        },
    })
}

