#[tokio::test]
async fn signing_out_ends_the_session_and_clears_the_cookies() {
    let pilot = Pilot::new().await;
    let cookie = "chase_sets_session=seller; chase_sets_guest_checkout=gst_1";
    let (status, headers, _) = pilot.send(sign_in_post("/sign-out", Some(cookie), "")).await;
    assert_eq!((status, headers[header::LOCATION].to_str().unwrap()), (StatusCode::SEE_OTHER, "/search"));
    let set = cookies_set(&headers);
    for name in ["chase_sets_session", "chase_sets_account_selection", "chase_sets_guest_checkout"] {
        assert!(set[name].contains("Max-Age=0"), "{name}: {set:?}");
    }
    let ended = auth_calls(&pilot, "/api/auth/sign-out");
    assert_eq!(ended.len(), 1);
    assert!(ended[0].headers[header::COOKIE].to_str().unwrap().contains("chase_sets_session=seller"), "the session it ends");
    assert_eq!(auth_calls(&pilot, "/api/auth/guest-checkout/exit").len(), 1, "a guest checkout ends too");

    // Leaving a guest checkout is the same (Auth's `guest-checkout-exit`).
    let (status, headers, _) =
        pilot.send(sign_in_post("/guest-checkout/exit", Some("chase_sets_guest_checkout=gst_2"), "")).await;
    assert_eq!((status, headers[header::LOCATION].to_str().unwrap()), (StatusCode::SEE_OTHER, "/search"));
    assert!(cookies_set(&headers)["chase_sets_guest_checkout"].contains("Max-Age=0"));
    assert_eq!(auth_calls(&pilot, "/api/auth/guest-checkout/exit").len(), 2);
}

const CONSENTS: &str = "/account/consents";

/// The consents Identity lists for `usr_seller` on `acc_seller`, newest first: a current Terms of
/// Service, an account's current Seller Agreement, a withdrawn Privacy Policy another one replaced,
/// a policy the page does not know with a version that is not a token, and another user's consent
/// (chase-sets/chase-sets#10707). A read that waits for 45 is still catching up. A withdrawal's
/// attempt decides an answer as a team write's does (`NO_RECORD`, `APPLIED_BEFORE`, `CHECK_DOWN`
/// are `indeterminate`); the old Privacy Policy is refused as superseded.
fn consents_api(method: &Method, uri: &Uri, headers: &HeaderMap) -> Option<Response> {
    let path = uri.path();
    let attempt = headers.get("idempotency-key").and_then(|v| v.to_str().ok()).unwrap_or_default();
    if path == "/api/identity/account-management/attempts" {
        let action = uri.query().unwrap_or_default().split('&').find_map(|p| p.strip_prefix("action=")).unwrap_or_default();
        if action != "withdraw" {
            return None;
        }
        return Some(match attempt {
            APPLIED_BEFORE => {
                Json(json!({ "outcome": "committed", "newlyCommitted": false, "destination": "/account/consents" }))
                    .into_response()
            }
            CHECK_DOWN => Json(json!({ "outcome": "indeterminate", "code": "INDETERMINATE" })).into_response(),
            _ => Json(json!({ "outcome": "not-recorded", "code": "not-recorded" })).into_response(),
        });
    }
    let rest = path.strip_prefix("/api/identity/consents")?;
    let consent = |id: &str,
                   subject: &str,
                   user: &str,
                   account: Option<&str>,
                   policy: &str,
                   version: &str,
                   withdrawn: Option<&str>,
                   current: bool| {
        json!({ "consent_id": id, "subject_type": subject, "user_id": user, "account_id": account, "policy_key": policy,
                "policy_version": version, "status": if withdrawn.is_some() { "withdrawn" } else { "recorded" },
                "recorded_at": "2026-10-01T15:00:00.000Z", "withdrawn_at": withdrawn,
                "updated_at": "2026-10-02T15:00:00.000Z", "is_current": current })
    };
    Some(match (method.as_str(), rest) {
        ("GET", "") if waits_for(headers).as_deref() == Some("45") => refusal(
            StatusCode::SERVICE_UNAVAILABLE,
            "projection_freshness_timeout",
            "Projection read model did not catch up to the requested write receipt before the freshness timeout.",
        ),
        ("GET", "") => {
            let items = [
                consent("cns_terms", "user", "usr_seller", None, "terms-of-service", "2026-05-01", None, true),
                consent("cns_seller", "account", "usr_seller", Some("acc_seller"), "seller-agreement", "2026-06-01", None, true),
                consent(
                    "cns_privacy_old",
                    "user",
                    "usr_seller",
                    None,
                    "privacy-policy",
                    "2025-01-01",
                    Some("2026-10-05T15:00:00.000Z"),
                    false,
                ),
                consent("cns_odd", "user", "usr_seller", None, "beta-terms", "1.0", None, false),
                consent("cns_else", "user", "usr_else", Some("acc_seller"), "terms-of-service", "2026-05-01", None, true),
            ];
            Json(json!({ "items": items, "total": 5, "count": 5 })).into_response()
        }
        _ if matches!(attempt, NO_RECORD | APPLIED_BEFORE | CHECK_DOWN) => {
            (StatusCode::SERVICE_UNAVAILABLE, Json(json!({ "outcome": "indeterminate", "code": "INDETERMINATE" })))
                .into_response()
        }
        ("POST", "/cns_privacy_old/withdraw") => {
            refusal(StatusCode::CONFLICT, "consent_superseded", "A newer consent replaced this one.")
        }
        ("POST", "/cns_terms/withdraw" | "/cns_seller/withdraw") => committed(
            StatusCode::OK,
            "identity",
            "42",
            json!({ "outcome": "committed", "newlyCommitted": true, "receipt": { "result": { "id": "cns_terms", "changed": true } } }),
        ),
        _ => StatusCode::NOT_FOUND.into_response(),
    })
}

/// The consent withdrawals the pilot sent: path and attempt.
fn consent_writes(pilot: &Pilot) -> Vec<(String, String)> {
    let calls = pilot.stand.calls.lock().unwrap();
    calls
        .iter()
        .filter(|c| c.path.starts_with("/api/identity/consents/") && c.method == Method::POST)
        .map(|c| (c.path.clone(), c.headers.get("idempotency-key").map(|v| v.to_str().unwrap().to_owned()).unwrap_or_default()))
        .collect()
}

#[tokio::test]
async fn the_consent_history_shows_only_the_users_own_and_offers_withdraw_on_a_current_one() {
    let pilot = Pilot::new().await;
    let (status, _, html) = pilot.send(get(CONSENTS, Some("buyer"))).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    let calls: Vec<String> = pilot.stand.calls.lock().unwrap().iter().map(|c| c.path.clone()).collect();
    assert!(
        calls.iter().any(|c| c == "/api/identity/consents?limit=50&offset=0&userId=usr_seller&accountId=acc_seller"),
        "the user's own, as marketplace asks: {calls:?}"
    );
    assert!(html.contains("Consent History") && html.contains("Audit history for agreements"), "{html}");
    assert!(
        html.contains("Terms of Service · Version 2026-05-01") && html.contains("Seller Agreement · Version 2026-06-01"),
        "{html}"
    );
    assert!(html.contains("Privacy Policy · Version 2025-01-01") && html.contains("Withdrawn"), "{html}");
    assert!(html.contains("Unrecognized consent policy: Beta Terms · Version unavailable"), "{html}");
    assert!(html.contains("Recorded Oct 1, 2026") && html.contains("· Withdrawn Oct 5, 2026"), "the moments: {html}");
    assert!(!html.contains("cns_else"), "another user's consent (#10707): {html}");
    assert!(html.contains(r#"commandfor="withdraw-consent-dialog-cns_terms""#), "{html}");
    assert!(html.contains(r#"commandfor="withdraw-consent-dialog-cns_seller""#), "{html}");
    assert!(
        !html.contains("withdraw-consent-dialog-cns_privacy_old") && !html.contains("withdraw-consent-dialog-cns_odd"),
        "only a current, recorded one: {html}"
    );
    assert!(html.contains("Withdraw Terms of Service consent?"), "{html}");
    let mut req = get(CONSENTS, Some("buyer"));
    req.headers_mut().insert(header::ACCEPT, "application/json".parse().unwrap());
    let (_, _, body) = pilot.send(req).await;
    let body: Value = serde_json::from_str(&body).unwrap();
    assert_eq!(body["data"]["consents"].as_array().map(Vec::len), Some(4), "{body}");

    let (status, headers, _) = pilot.send(get(CONSENTS, None)).await;
    assert_eq!(status, StatusCode::SEE_OTHER);
    assert!(headers[header::LOCATION].to_str().unwrap().starts_with("/sign-in?returnTo=%2Faccount%2Fconsents"), "{headers:?}");
}

#[tokio::test]
async fn a_withdrawal_sends_its_attempt_and_the_page_is_read_after_it() {
    let pilot = Pilot::new().await;
    let body = format!("intent=withdraw&attempt={ATTEMPT}&consent_id=cns_terms");
    let (status, headers, _) = pilot.send(post(CONSENTS, "buyer", &body, false)).await;
    assert_eq!(status, StatusCode::SEE_OTHER);
    let to = headers[header::LOCATION].to_str().unwrap().to_owned();
    assert!(to.starts_with("/account/consents?after_write=") && to.ends_with(&format!("&saved={ATTEMPT}")), "{to}");
    assert_eq!(consent_writes(&pilot), [("/api/identity/consents/cns_terms/withdraw".to_owned(), ATTEMPT.to_owned())]);
    let (_, _, html) = pilot.send(get(&to, Some("buyer"))).await;
    assert!(html.contains("Your change was saved"), "{html}");
    let calls = pilot.stand.calls.lock().unwrap().clone();
    let read = calls.iter().rev().find(|c| c.path.starts_with("/api/identity/consents?")).unwrap();
    assert_eq!(waits_for(&read.headers).as_deref(), Some("42"), "read after the withdrawal's receipt");

    let (status, _, html) = pilot.send(get(&format!("{CONSENTS}?after_write={}", receipt_at("45")), Some("buyer"))).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    assert!(html.contains("Terms of Service") && html.contains("still updating"), "the history as it was: {html}");
}

#[tokio::test]
async fn a_refused_withdrawal_says_why_and_a_lost_answer_is_asked_about() {
    let pilot = Pilot::new().await;
    let refused = |body: String| post(CONSENTS, "buyer", &body, false);
    let (status, _, html) = pilot.send(refused(format!("intent=forget&attempt={ATTEMPT}&consent_id=cns_terms"))).await;
    assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
    assert!(html.contains("Unknown consent action."), "{html}");
    // An attempt that is not a submit key is refused by the form's reader, before the handler.
    let (status, _, html) = pilot.send(refused("intent=withdraw&attempt=nope&consent_id=cns_terms".into())).await;
    assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
    assert!(html.contains("submit key"), "{html}");
    let (status, _, html) = pilot.send(refused(format!("intent=withdraw&attempt={ATTEMPT}&consent_id=+"))).await;
    assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
    assert!(html.contains("Choose a consent to withdraw."), "{html}");
    assert!(consent_writes(&pilot).is_empty(), "nothing sent for a form the page cannot send");
    // Superseded: Identity's rule, a refusal that recorded nothing.
    let (status, _, html) = pilot.send(refused(format!("intent=withdraw&attempt={ATTEMPT}&consent_id=cns_privacy_old"))).await;
    assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
    assert!(html.contains("No change was recorded"), "{html}");

    // No answer that says what happened: the lookup settles it, or the page asks again with Withdraw off.
    let (status, headers, _) =
        pilot.send(refused(format!("intent=withdraw&attempt={APPLIED_BEFORE}&consent_id=cns_terms"))).await;
    assert_eq!(status, StatusCode::SEE_OTHER);
    assert!(headers[header::LOCATION].to_str().unwrap().contains(&format!("saved={APPLIED_BEFORE}")), "{headers:?}");
    let (_, headers, _) = pilot.send(refused(format!("intent=withdraw&attempt={CHECK_DOWN}&consent_id=cns_terms"))).await;
    let to = headers[header::LOCATION].to_str().unwrap().to_owned();
    assert_eq!(to, format!("/account/consents?check={CHECK_DOWN}&target=cns_terms"));
    let (_, _, html) = pilot.send(get(&to, Some("buyer"))).await;
    assert!(html.contains("We could not confirm the result") && html.contains("Check again"), "{html}");
    let dialog = html.find(r#"id="withdraw-consent-dialog-cns_terms""#).unwrap();
    assert!(
        html[dialog..].split("</dialog>").next().unwrap().contains(" disabled>"),
        "the withdrawal it would repeat is off: {html}"
    );
    let other = html.find(r#"id="withdraw-consent-dialog-cns_seller""#).unwrap();
    assert!(!html[other..].split("</dialog>").next().unwrap().contains(" disabled>"), "another consent's is not: {html}");
    let (status, _, html) = pilot.send(refused(format!("intent=withdraw&attempt={NO_RECORD}&consent_id=cns_terms"))).await;
    assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "the lookup says nothing was recorded");
    assert!(html.contains("No change was recorded"), "{html}");
}

const MONEY: &str = "/account/desk/money";

/// Settlement's reads and writes for the money page's sessions (`banker`, `payout_reader`,
/// `busy_banker`). The wallet holds $26.83 with $106.96 pending; payout setup is ready. Three payouts:
/// one failed, one in transit since Monday the 26th with no provider reference, one paid, with
/// Settlement's summary of them: the one in transit arrives first, the other two are blocked, and
/// only an account that may request can. `busy_banker`'s summary is past Settlement's cap, so it
/// leaves the next payout and the blocked ones out. The wallet's activity: a sale and the
/// adjustment `WADJ-1`, which is the only one the account has. A preview of 1.00 is refused below the
/// minimum; Request a payout of 13.00 is refused for the policy's hold, and any other is `pyo_new`,
/// at position 42.
fn money_api(session: &str, method: &Method, uri: &Uri, body: &str) -> Option<Response> {
    if !matches!(session, "banker" | "payout_reader" | "busy_banker") {
        return None;
    }
    let sent: Value = serde_json::from_str(body).unwrap_or_default();
    let payout = |id: &str, status: &str, sent_at: Option<&str>, reason: Option<&str>| {
        json!({ "payout_id": id, "account_id": "acc_seller", "display_reference": format!("PYO-{id}"), "status": status,
                "amount": "10.00", "requested_amount": "10.00", "fee_amount": "0.27", "net_amount": "9.73", "currency_code": "usd",
                "requested_at": "2026-10-23T15:00:00.000Z", "updated_at": "2026-10-26T12:00:00.000Z", "sent_at": sent_at,
                "completed_at": if status == "completed" { Some("2026-10-24T15:00:00.000Z") } else { None },
                "failed_at": reason.map(|_| "2026-10-23T15:10:00.000Z"), "failure_reason": reason,
                "provider_failure_code": null, "provider_payout_reference": if status == "completed" { Some("po_1") } else { None } })
    };
    Some(match (method.as_str(), uri.path()) {
        ("GET", "/api/settlement/wallet") => Json(json!({
            "account_id": "acc_seller", "currency_code": "usd", "available_balance_amount": "26.83", "pending_balance_amount": "106.96",
        }))
        .into_response(),
        ("GET", "/api/settlement/wallet/entries") => Json(json!({ "items": [
            { "ledger_entry_id": "led_sale", "kind": "sale", "direction": "credit", "amount": "56.83", "currency_code": "usd",
              "funds_status": "available", "description": "Sale of Charizard", "posted_at": "2026-10-20T15:00:00.000Z",
              "adjustment_display_reference": null },
            { "ledger_entry_id": "led_adj", "kind": "adjustment", "direction": "credit", "amount": "30.00", "currency_code": "usd",
              "funds_status": "pending", "description": null, "posted_at": "2026-10-21T15:00:00.000Z",
              "adjustment_display_reference": "WADJ-1" },
        ], "total": 2, "count": 2 }))
        .into_response(),
        ("GET", "/api/settlement/payouts") => {
            let complete = session != "busy_banker";
            let blocked = |id: &str, reason: &str, kind: &str, next: &str| {
                json!({ "payout_id": id, "account_id": "acc_seller", "reference": format!("PYO-{id}"), "block_reason": reason,
                        "kind": kind, "next_action": next, "observed_at": "2026-10-26T12:00:00.000Z" })
            };
            let may = session != "payout_reader";
            Json(json!({
                "items": [
                    payout("pyo_failed", "failed", None, Some("Bank account temporarily unavailable")),
                    payout("pyo_moving", "in-transit", Some("2026-10-26T12:00:00.000Z"), None),
                    payout("pyo_paid", "completed", Some("2026-10-23T16:00:00.000Z"), None),
                ],
                "total": 3, "count": 3,
                "completeness": if complete { json!({ "kind": "complete", "total": 3 }) }
                    else { json!({ "kind": "bounded-incomplete", "total": 251, "cap": 250, "reason": "payout-summary-cap-exceeded" }) },
                "next_payout": if complete { json!({ "payout_id": "pyo_moving", "amount": "9.73", "requested_amount": "10.00",
                    "fee_amount": "0.27", "currency_code": "usd", "estimated_arrival_at": "2026-10-29T12:00:00.000Z" }) } else { Value::Null },
                "blocked_payouts": if complete { json!([
                    blocked("pyo_failed", "Bank account temporarily unavailable", "failed", "retry"),
                    blocked("pyo_moving", "payout-reconciliation-required", "missing-provider-reference", "run-reconciliation"),
                ]) } else { json!([]) },
                "availability": {
                    "can_request": may,
                    "unavailable_reasons": if may { json!([]) } else { json!(["payout-request-permission-required"]) },
                    "unavailable_reason_details": [],
                },
            }))
            .into_response()
        }
        ("GET", "/api/settlement/payout-readiness") => Json(json!({
            "account_id": "acc_seller", "status": "ready", "missing_requirements": [], "provider_reference": "acct_1",
            "updated_at": "2026-10-01T00:00:00.000Z", "next_step": "none", "support_recommended": false,
            "provider_setup_available": false, "provider_management_available": true,
        }))
        .into_response(),
        ("GET", "/api/settlement/payouts/quick-amounts") => Json(json!({
            "currency_code": "usd", "minimum_amount": "5.00", "maximum_amount": "10000.00", "full_available_amount": "26.83",
        }))
        .into_response(),
        ("GET", path) if path.starts_with("/api/settlement/payouts/") => {
            let mut one = match &path["/api/settlement/payouts/".len()..] {
                "pyo_failed" => payout("pyo_failed", "failed", None, Some("Bank account temporarily unavailable")),
                "pyo_moving" => payout("pyo_moving", "in-transit", Some("2026-10-26T12:00:00.000Z"), None),
                "pyo_paid" => payout("pyo_paid", "completed", Some("2026-10-23T16:00:00.000Z"), None),
                "pyo_noted" => payout("pyo_noted", "requested", None, None),
                // `pyo_new` is the one Request a payout makes, which Settlement has not caught up to.
                _ => return Some(refusal(StatusCode::NOT_FOUND, "not_found", "Payout not found.")),
            };
            if one["status"] == "completed" {
                one["provider_transfer_reference"] = json!("tr_1");
                one["last_provider_event_at"] = json!("2026-10-24T14:00:00.000Z");
                one["last_reconciled_at"] = json!("2026-10-24T15:30:00.000Z");
            }
            if one["status"] == "requested" {
                one["note"] = json!("Rent for November");
            }
            Json(one).into_response()
        }
        ("GET", "/api/settlement/wallet/adjustments/WADJ-1") => Json(json!({
            "status": "posted", "display_reference": "WADJ-1", "direction": "credit", "amount": "30.00", "currency_code": "usd",
            "reason_code": "goodwill-cash-credit", "requested_at": "2026-10-21T15:00:00.000Z", "posted_at": "2026-10-21T15:05:00.000Z",
            "available_balance_before": "0.00", "available_balance_after": "30.00", "reversed_at": null,
            "reversal_of_display_reference": null, "reversed_by_display_reference": null,
        }))
        .into_response(),
        ("GET", path) if path.starts_with("/api/settlement/wallet/adjustments/") => {
            refusal(StatusCode::NOT_FOUND, "not_found", "Wallet adjustment not found.")
        }
        ("POST", "/api/settlement/payouts/preview") => {
            let amount = match (sent["amountSelection"].as_str(), sent["amount"].as_str()) {
                (Some("minimum"), _) => "5.00".to_owned(),
                (Some(_), _) => "26.83".to_owned(),
                (None, Some("1.00")) => {
                    return Some(refusal(StatusCode::BAD_REQUEST, "validation_failed", "Enter an amount above the minimum payout."));
                }
                (None, Some(amount)) => amount.to_owned(),
                (None, None) => return Some(refusal(StatusCode::BAD_REQUEST, "validation_failed", "Payout amount is required.")),
            };
            Json(json!({
                "account_id": "acc_seller", "requested_amount": amount, "fee_amount": "0.27", "net_amount": "net",
                "fee_lines": [{ "code": "payout-fee", "label": "Payout fee", "amount": "0.27" }], "currency_code": "usd",
                "available_balance_amount": "26.83", "estimated_wallet_balance_after": "21.83", "can_request": amount != "26.83",
                "unavailable_reasons": [], "unavailable_reason_details": if amount == "26.83" {
                    json!([{ "code": "payout-release-hold-active", "message": "Recent sales are held until delivery and risk checks clear." }])
                } else { json!([]) },
            }))
            .into_response()
        }
        ("POST", "/api/settlement/payouts") if sent["amount"] == "13.00" => {
            refusal(StatusCode::BAD_REQUEST, "validation_failed", "Recent sales are held until delivery and risk checks clear.")
        }
        ("POST", "/api/settlement/payouts") => {
            committed(StatusCode::CREATED, "settlement", "42", json!({ "id": "pyo_new", "version": 1, "status": "requested" }))
        }
        ("POST", "/api/settlement/payouts/reconciliation/run") => {
            Json(json!({ "progress": { "message": "Checked 1 payout with the provider." } })).into_response()
        }
        _ => return None,
    })
}

/// Settlement's payout setup for `setter` (not started: the provider's onboarding and the seller
/// agreement are missing, two details for verification review), `restricted_setter` (restricted for
/// overdue details, with a provider account and a missing payout account) and `banker` (ready).
/// Refresh is committed at position 51 (`banker`'s comes back ready); a session is
/// `accs_secret_{which}`, but `restricted_setter`'s management session needs a recent sign-in.
fn payout_setup_api(session: &str, method: &Method, uri: &Uri) -> Option<Response> {
    if !matches!(session, "setter" | "restricted_setter" | "banker") {
        return None;
    }
    let restricted = session == "restricted_setter";
    let ready = session == "banker";
    let readiness = if ready {
        json!({ "account_id": "acc_seller", "status": "ready", "missing_requirements": [], "provider_reference": "acct_1",
                "onboarding_status": "complete", "transfer_capability_status": "active", "payout_capability_status": "active",
                "payout_destination_status": "ready", "updated_at": "2026-10-01T00:00:00.000Z",
                "next_step": "none", "support_recommended": false, "provider_setup_available": false,
                "provider_management_available": true })
    } else if restricted {
        json!({ "account_id": "acc_seller", "status": "restricted", "missing_requirements": ["external_account"],
                "advisory_requirements": ["company.tax_id"], "disabled_reason": "requirements.past_due",
                "requirements_deadline": "2026-11-05T00:00:00.000Z", "provider_reference": "acct_9",
                "onboarding_status": "pending", "transfer_capability_status": "inactive", "payout_capability_status": "inactive",
                "payout_destination_status": "missing", "updated_at": "2026-10-28T12:00:00.000Z",
                "next_step": "restricted_past_due", "support_recommended": true, "provider_setup_available": true,
                "provider_management_available": true })
    } else {
        json!({ "account_id": "acc_seller", "status": "not-started", "missing_requirements": ["provider-onboarding", "seller-agreement"],
                "provider_reference": null, "onboarding_status": "not-started", "transfer_capability_status": "inactive",
                "payout_capability_status": "inactive", "payout_destination_status": "missing", "updated_at": null,
                "next_step": "complete_requirements", "support_recommended": true, "provider_setup_available": true,
                "provider_management_available": false })
    };
    let step = |id: &str, label: &str, status: &str| json!({ "id": id, "label": label, "status": status, "detail": format!("{label}: {status}.") });
    Some(match (method.as_str(), uri.path()) {
        ("GET", "/api/settlement/payout-readiness") if !ready => Json(readiness).into_response(),
        ("GET", "/api/settlement/payout-setup/progress") => {
            let groups = if ready {
                json!([])
            } else if restricted {
                json!([{ "id": "payout-account", "label": "Payout account", "count": 1, "detail": "" }])
            } else {
                json!([{ "id": "verification-review", "label": "Verification review", "count": 2, "detail": "" }])
            };
            let advisory = if restricted { json!([{ "id": "identity-and-business", "count": 1 }]) } else { json!([]) };
            Json(json!({
                "missing_requirement_groups": groups, "advisory_requirement_groups": advisory,
                "steps": [step("payout-setup", "Payout setup", if ready { "ready" } else { "not-started" }),
                          step("payout-destination", "Payout destination", if ready { "ready" } else { "needs-attention" })],
            }))
            .into_response()
        }
        ("POST", "/api/settlement/payout-setup/refresh") => {
            let mut body = readiness;
            body["commandReceipt"] = Value::Null;
            committed(StatusCode::OK, "settlement", "51", body)
        }
        ("POST", "/api/settlement/payout-setup/account-management-embedded-session") if restricted => {
            refusal(StatusCode::BAD_REQUEST, "step_up_required", "Confirm it is you before managing payout account details.")
        }
        ("POST", path) if path.starts_with("/api/settlement/payout-setup/") && path.ends_with("session") => {
            let which = path.trim_start_matches("/api/settlement/payout-setup/");
            Json(json!({ "clientSecret": format!("accs_secret_{which}") })).into_response()
        }
        _ => return None,
    })
}

const PAYOUT_SETUP: &str = "/account/desk/settings";

#[tokio::test]
async fn payout_setup_shows_the_status_what_it_needs_and_stripes_form() {
    let pilot = Pilot::new().await;
    let (status, headers, html) = pilot.send(get(PAYOUT_SETUP, Some("setter"))).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    let shown = text(&html);
    assert!(shown.contains("Settlement Payout setup Keep payout destination"), "{shown}");
    assert!(shown.contains("Not started Start payout setup Add the required account and payout destination details"), "{shown}");
    assert!(shown.contains("Set up payouts") && shown.contains("Last checked: Not checked yet"), "{shown}");
    // Not ready and something to do (Settlement's `complete_requirements`): the groups' words.
    assert!(shown.contains("Payout setup details need attention Open payout setup to complete: Verification review."), "{shown}");
    assert!(
        shown.contains("Payout setup: not-started.") && shown.contains("Payout destination: needs-attention."),
        "the steps: {shown}"
    );
    assert!(
        shown.contains("Support details 2 provider details available")
            && shown.contains("Verification review: 2 detail(s) need attention"),
        "{shown}"
    );
    assert!(
        html.contains(r#"name="intent" value="refresh-payout-setup""#) && html.contains(r#"name="mode" value="setup""#),
        "{html}"
    );
    // Stripe's onboarding form, its session from the pilot; no notifications without a provider account.
    assert!(html.contains("/account/desk/settings/session?which=onboarding"), "{html}");
    assert!(!html.contains("which=notifications") && !shown.contains("Manage details"), "{html}");
    assert!(shown.contains("Loading secure payout setup"), "{shown}");
    // Connect.js's sources on this page, and the opener Stripe's sign-in needs (todd-skelton/corten#318).
    let csp = headers[header::CONTENT_SECURITY_POLICY].to_str().unwrap();
    assert!(
        csp.contains("https://connect-js.stripe.com") && csp.contains("'sha256-0hAheEzaMe6uXIKV4EehS9pu1am1lj/KnnzrOYqckXk='"),
        "{csp}"
    );
    assert_eq!(headers["cross-origin-opener-policy"], "unsafe-none");
    // Every other page keeps same-origin and no Connect.js.
    let (_, headers, _) = pilot.send(get(MONEY, Some("banker"))).await;
    assert_eq!(headers["cross-origin-opener-policy"], "same-origin");
    assert!(!headers[header::CONTENT_SECURITY_POLICY].to_str().unwrap().contains("connect-js"));
}

#[tokio::test]
async fn restricted_payout_setup_says_why_offers_support_and_manages_with_a_provider_account() {
    let pilot = Pilot::new().await;
    let (status, _, html) = pilot.send(get(PAYOUT_SETUP, Some("restricted_setter"))).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    let shown = text(&html);
    assert!(shown.contains("Needs attention Payout setup needs attention."), "{shown}");
    assert!(shown.contains("Payout setup is restricted Required payout details are overdue."), "past_due: {shown}");
    assert!(shown.contains("Contact support"), "{shown}");
    assert!(shown.contains("Upcoming payout requirements"), "{shown}");
    assert!(html.contains("<details") && html.contains(" open"), "restricted opens the fold: {html}");
    assert!(shown.contains("Payout destination Missing") && shown.contains("Act by"), "{shown}");
    assert!(html.contains("which=notifications") && html.contains("which=onboarding"), "{html}");
    assert!(html.contains(r#"href="/account/desk/settings?mode=manage""#) && shown.contains("Manage details"), "{html}");

    let (_, _, html) = pilot.send(get(&format!("{PAYOUT_SETUP}?mode=manage"), Some("restricted_setter"))).await;
    assert!(html.contains("which=management") && text(&html).contains("Manage payout details"), "{html}");
    assert!(html.contains(r#"name="mode" value="management""#) && text(&html).contains("Setup view"), "{html}");
    // Management without a provider account is setup (`resolvePayoutSetupMode`).
    let (_, _, html) = pilot.send(get(&format!("{PAYOUT_SETUP}?mode=manage"), Some("setter"))).await;
    assert!(html.contains("which=onboarding") && !html.contains("which=management"), "{html}");

    // Ready: no form, Request payout instead.
    let (_, _, html) = pilot.send(get(PAYOUT_SETUP, Some("banker"))).await;
    let shown = text(&html);
    assert!(shown.contains("Payouts are ready You can request payouts") && shown.contains("Request payout"), "{shown}");
    assert!(!html.contains("which=onboarding") && html.contains("which=notifications"), "{html}");
}

