#[tokio::test]
async fn refresh_reads_the_page_after_it_or_goes_back_once_setup_is_ready() {
    let pilot = Pilot::new().await;
    let (status, headers, _) = pilot
        .send(post(&format!("{PAYOUT_SETUP}?mode=manage"), "setter", "intent=refresh-payout-setup&mode=management", false))
        .await;
    assert_eq!(status, StatusCode::SEE_OTHER);
    let to = headers[header::LOCATION].to_str().unwrap().to_owned();
    assert!(to.starts_with("/account/desk/settings?mode=manage&setup=updated&afterWrite="), "{to}");
    let (_, _, html) = pilot.send(get(&to, Some("setter"))).await;
    assert!(text(&html).contains("Setup status checked Payout setup status was refreshed."), "{html}");
    let read =
        pilot.stand.calls.lock().unwrap().iter().rev().find(|c| c.path == "/api/settlement/payout-readiness").cloned().unwrap();
    assert_eq!(waits_for(&read.headers).as_deref(), Some("51"), "read after the refresh");

    // Ready, with an account page to go back to: there. Not an account page: the page.
    let (status, headers, _) = pilot
        .send(post(&format!("{PAYOUT_SETUP}?returnTo=%2Faccount%2Fdesk%2Fmoney"), "banker", "intent=refresh-payout-setup", false))
        .await;
    assert_eq!(status, StatusCode::SEE_OTHER);
    assert_eq!(headers[header::LOCATION], "/account/desk/money");
    let (_, headers, _) = pilot
        .send(post(&format!("{PAYOUT_SETUP}?returnTo=%2F%2Fevil.test%2F"), "banker", "intent=refresh-payout-setup", false))
        .await;
    assert!(headers[header::LOCATION].to_str().unwrap().starts_with("/account/desk/settings?setup=updated"), "{headers:?}");
    // Any other intent goes back to the page in its mode, writing nothing.
    let before = pilot.stand.calls.lock().unwrap().len();
    let (status, headers, _) = pilot.send(post(PAYOUT_SETUP, "setter", "intent=start-payout-setup&mode=management", false)).await;
    assert_eq!(status, StatusCode::SEE_OTHER);
    assert_eq!(headers[header::LOCATION], "/account/desk/settings?mode=manage");
    assert!(pilot.stand.calls.lock().unwrap()[before..].iter().all(|c| c.method != Method::POST), "nothing sent");
}

#[tokio::test]
async fn a_connect_session_is_json_kept_by_no_cache_and_says_when_to_sign_in_again() {
    let pilot = Pilot::new().await;
    let (status, headers, body) =
        pilot.send(post(&format!("{PAYOUT_SETUP}/session?which=onboarding"), "setter", "", false)).await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert!(headers[header::CACHE_CONTROL].to_str().unwrap().contains("no-store"), "{headers:?}");
    let answer: Value = serde_json::from_str(&body).unwrap();
    assert_eq!(answer["secret"], "accs_secret_embedded-session", "{body}");
    let sent = pilot.stand.calls.lock().unwrap().iter().find(|c| c.path.ends_with("/embedded-session")).cloned().unwrap();
    assert_eq!(serde_json::from_str::<Value>(&sent.body).unwrap(), json!({ "contactEmail": "seller@chasesets.test" }));

    let (_, _, body) =
        pilot.send(post(&format!("{PAYOUT_SETUP}/session?which=notifications"), "restricted_setter", "", false)).await;
    assert_eq!(serde_json::from_str::<Value>(&body).unwrap()["secret"], "accs_secret_notification-banner-session");
    let (status, _, body) =
        pilot.send(post(&format!("{PAYOUT_SETUP}/session?which=management"), "restricted_setter", "", false)).await;
    assert_eq!(status, StatusCode::OK);
    let answer: Value = serde_json::from_str(&body).unwrap();
    assert_eq!(answer["code"], "step_up_required", "{body}");
    assert!(answer["secret"].is_null(), "{body}");
    let sent = pilot
        .stand
        .calls
        .lock()
        .unwrap()
        .iter()
        .find(|c| c.path.ends_with("/account-management-embedded-session"))
        .cloned()
        .unwrap();
    assert_eq!(serde_json::from_str::<Value>(&sent.body).unwrap(), json!({}), "management sends no email");
}

/// The money page's calls to Settlement's writes: path and body.
fn money_writes(pilot: &Pilot) -> Vec<(String, Value, Option<String>)> {
    let calls = pilot.stand.calls.lock().unwrap();
    calls
        .iter()
        .filter(|c| c.path.starts_with("/api/settlement/") && c.method == Method::POST)
        .map(|c| {
            let key = c.headers.get("idempotency-key").map(|v| v.to_str().unwrap().to_owned());
            (c.path.clone(), serde_json::from_str(&c.body).unwrap_or_default(), key)
        })
        .collect()
}

#[tokio::test]
async fn the_money_page_shows_the_wallet_the_payouts_and_what_needs_a_next_step() {
    let pilot = Pilot::new().await;
    let (status, _, html) = pilot.send(get(MONEY, Some("banker"))).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    assert!(html.contains("Money at a glance") && html.contains("$26.83") && html.contains("$106.96 pending"), "{html}");
    // Settlement's next payout and blocked ones, as it answers them.
    assert!(html.contains("$9.73") && html.contains("Estimated by Oct 29, 2026"), "the next payout: {html}");
    assert!(html.contains("2 payouts need attention"), "the failed one and the one with no provider reference: {html}");
    assert!(
        html.contains(r#"data-blocked-payout="pyo_failed""#) && html.contains("Bank account temporarily unavailable"),
        "{html}"
    );
    assert!(html.contains(r#"data-blocked-payout="pyo_moving""#) && html.contains("Awaiting payout confirmation"), "{html}");
    assert!(html.contains(r#"value="retry""#) && html.contains(r#"value="run-reconciliation""#), "each one's next step: {html}");
    assert!(!html.contains(r#"data-blocked-payout="pyo_paid""#), "{html}");
    assert!(
        html.contains(r#"commandfor="payout-breakdown-pyo_paid""#) && html.contains(r#"<dialog id="payout-breakdown-pyo_paid""#),
        "{html}"
    );
    assert!(html.contains("Sale of Charizard") && html.contains("Wallet adjustment"), "the activity: {html}");
    assert!(html.contains("drawer=wallet-adjustment&amp;entity=WADJ-1"), "the adjustment's breakdown: {html}");
    assert!(html.contains("Minimum · $5.00") && html.contains("Full available · $26.83"), "the policy's amounts: {html}");
    assert!(html.contains("Manage payout account") && !html.contains("Finish payout setup"), "setup is done: {html}");
    assert!(!html.contains(r#"id="adjustment-dialog""#), "no adjustment open: {html}");

    let mut req = get(MONEY, Some("banker"));
    req.headers_mut().insert(header::ACCEPT, "application/json".parse().unwrap());
    let (_, _, body) = pilot.send(req).await;
    let body: Value = serde_json::from_str(&body).unwrap();
    assert_eq!(body["data"]["summary"]["next_payout"]["estimated_arrival_at"], "2026-10-29T12:00:00.000Z", "{body}");
    assert_eq!(body["data"]["summary"]["availability"]["can_request"], true, "{body}");
    assert!(
        !pilot.stand.calls.lock().unwrap().iter().any(|c| c.path == "/api/settlement/payout-readiness"),
        "the page reads availability from the payouts, not readiness"
    );

    let (status, _, html) = pilot.send(get(MONEY, Some("payout_reader"))).await;
    assert_eq!(status, StatusCode::OK);
    assert!(!html.contains(r#"value="retry""#) && !html.contains("Manage payout account"), "a reader's page: {html}");
    let preview = html.find("Preview payout</button>").map(|i| &html[i.saturating_sub(80)..i]).unwrap_or_default();
    assert!(preview.contains("disabled"), "a reader may not request: {preview}");
    assert!(text(&html).contains("Request permission is required to request a"), "Settlement's reason: {html}");

    // Past Settlement's cap the summary leaves out the next payout and the blocked ones, and says so.
    let (status, _, html) = pilot.send(get(MONEY, Some("busy_banker"))).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    let shown = text(&html);
    assert!(shown.contains("Payout history is incomplete"), "{shown}");
    assert!(!shown.contains("Estimated by") && !html.contains("data-blocked-payout"), "{html}");

    let (status, _, _) = pilot.send(get(MONEY, Some("buyer"))).await;
    assert_eq!(status, StatusCode::FORBIDDEN, "without payouts.view");
    let (status, headers, _) = pilot.send(get(MONEY, None)).await;
    assert_eq!(status, StatusCode::SEE_OTHER);
    assert!(
        headers[header::LOCATION].to_str().unwrap().starts_with("/sign-in?returnTo=%2Faccount%2Fdesk%2Fmoney"),
        "{headers:?}"
    );
}

