#[tokio::test]
async fn checkout_start_for_a_visitor_starts_a_guest_checkout_and_keeps_its_token() {
    let pilot = Pilot::new().await;
    let cookie = "chase_sets_anonymous_cart=anon_full";
    let (status, headers, html) =
        pilot.send(visitor_post(START_LISTING, Some(cookie), "entryAttemptKey=chkentry_01JBXQ5V7Z3N4M8K2R6T9GUEST")).await;
    assert_eq!(status, StatusCode::SEE_OTHER, "{html}");
    assert!(headers[header::LOCATION].to_str().unwrap().starts_with("/checkout/buy/session/chk_1"), "{headers:?}");
    let set: Vec<_> = headers.get_all(header::SET_COOKIE).iter().map(|v| v.to_str().unwrap().to_owned()).collect();
    assert!(set.iter().any(|c| c.starts_with("chase_sets_guest_checkout=gst_new;") && c.contains("Max-Age=")), "{set:?}");
    assert!(set.iter().any(|c| c.starts_with("chase_sets_anonymous_cart=;")), "the guest cart is forgotten: {set:?}");
    let calls = pilot.stand.calls.lock().unwrap().clone();
    assert_eq!(calls.iter().filter(|c| c.path == "/api/auth/guest-checkout/start").count(), 1);
    let started = calls.iter().find(|c| c.path.ends_with("/checkout-sessions")).unwrap();
    let as_guest = started.headers[header::COOKIE].to_str().unwrap();
    assert_eq!(as_guest, "chase_sets_guest_checkout=gst_new", "the session starts as the new guest");

    // An offer needs an account: nothing starts.
    let offer =
        "/checkout/buy/readiness?source=offer-intent&productId=prd_vault&offerPriceAmount=24.50&offerPriceCurrencyCode=USD";
    let (status, _, html) = pilot.send(visitor_post(offer, None, "")).await;
    assert_eq!(status, StatusCode::UNAUTHORIZED, "{html}");
    assert!(text(&html).contains("Sign in required"), "{html}");
    // An empty guest cart: the page says so, and no guest identity is started.
    let (status, _, html) = pilot.send(visitor_post("/checkout/buy/readiness", None, "source=cart")).await;
    assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "{html}");
    assert!(text(&html).contains("Your Buy Cart is empty"), "{html}");
    assert_eq!(pilot.stand.calls.lock().unwrap().iter().filter(|c| c.path == "/api/auth/guest-checkout/start").count(), 1);
}

/// The checkout-session entries and entry attempt lookups the stand-in received.
fn entry_calls(pilot: &Pilot) -> (Vec<Call>, Vec<Call>) {
    let calls = pilot.stand.calls.lock().unwrap().clone();
    let sent = calls.iter().filter(|c| c.method == Method::POST && c.path.ends_with("/checkout-sessions")).cloned().collect();
    let looked = calls.iter().filter(|c| c.path.starts_with(CART_ATTEMPTS)).cloned().collect();
    (sent, looked)
}

#[tokio::test]
async fn checkout_start_looks_an_entry_whose_answer_was_lost_up_once_and_never_sends_it_again() {
    let pilot = Pilot::new().await;
    let key = "chkentry_lost_0000000000000000";
    let (status, headers, html) = pilot.send(post(START_LISTING, "buyer", &format!("entryAttemptKey={key}"), false)).await;
    assert_eq!(status, StatusCode::SEE_OTHER, "{html}");
    let to = headers[header::LOCATION].to_str().unwrap();
    assert!(to.starts_with("/checkout/buy/session/chk_lost?afterWrite="), "the kept attempt's session, after its commit: {to}");
    let (sent, looked) = entry_calls(&pilot);
    assert_eq!(sent.len(), 1, "the entry is sent once");
    // The lookup names exactly what was sent: its key, kind, target and the owner's request hash.
    let body: Value = serde_json::from_str(&sent[0].body).unwrap();
    let hash = crate::checkout_entry::request_hash(&body, None);
    let paths: Vec<_> = looked.iter().map(|c| c.path.clone()).collect();
    assert_eq!(paths, [format!("{CART_ATTEMPTS}{key}?kind=checkout-entry&target=session&requestHash={hash}")]);
}

#[tokio::test]
async fn checkout_start_an_entry_no_lookup_can_show_pauses_continue_and_sends_nothing_more() {
    let pilot = Pilot::new().await;
    let body = "entryAttemptKey=chkentry_unknown_000000000000000";
    let (status, _, html) = pilot.send(post(START_LISTING, "buyer", body, false)).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    assert!(text(&html).contains("We could not confirm whether your checkout started."), "{html}");
    assert!(html.contains(r#"id="checkout-start-entry-result""#), "{html}");
    assert!(html.contains(r#"checkout-start-page__large" disabled>"#), "Continue is off: {html}");
    let (sent, looked) = entry_calls(&pilot);
    assert_eq!((sent.len(), looked.len()), (1, 1), "sent once, looked up once");

    // A closed checkout is Checkout's decided refusal, not a lost answer: nothing is looked up.
    let body = "entryAttemptKey=chkentry_closed_00000000000000000";
    let (status, _, html) = pilot.send(post(START_LISTING, "buyer", body, false)).await;
    assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{html}");
    assert!(text(&html).contains("Checkout is closed"), "{html}");
    assert_eq!(entry_calls(&pilot).1.len(), 1, "no second lookup");
}

#[tokio::test]
async fn checkout_start_sends_nothing_for_a_key_that_is_not_one_and_a_used_one_is_out_of_date() {
    let pilot = Pilot::new().await;
    // Malformed, or missing on an entry that is not the cart's: refused before anything is sent.
    for body in ["entryAttemptKey=short", "entryAttemptKey=has+a+space+but+is+long+enough", ""] {
        let (status, _, html) = pilot.send(post(START_LISTING, "buyer", body, false)).await;
        assert_eq!(status, StatusCode::CONFLICT, "{body:?}: {html}");
        assert!(text(&html).contains("This checkout page is out of date"), "{body:?}: {html}");
        assert!(html.contains(r#">Refresh checkout</a>"#), "{body:?}: {html}");
    }
    let (status, _, html) = pilot.send(visitor_post(START_LISTING, None, "entryAttemptKey=short")).await;
    assert_eq!(status, StatusCode::CONFLICT, "{html}");
    let calls = pilot.stand.calls.lock().unwrap().clone();
    assert!(calls.iter().all(|c| !c.path.ends_with("/checkout-sessions")), "nothing was sent");
    assert!(calls.iter().all(|c| c.path != "/api/auth/guest-checkout/start"), "no guest was started");

    // A key Checkout already kept for other details: the same recovery.
    let (status, _, html) =
        pilot.send(post(START_LISTING, "buyer", "entryAttemptKey=conflict-0000000000000000000000", false)).await;
    assert_eq!(status, StatusCode::CONFLICT, "{html}");
    assert!(text(&html).contains("This checkout page is out of date"), "{html}");
}

#[tokio::test]
async fn checkout_start_for_a_visitor_whose_entry_is_ambiguous_keeps_the_one_guest_it_started_as() {
    let pilot = Pilot::new().await;
    let body = "entryAttemptKey=chkentry_unknown_000000000000000";
    let (status, headers, html) = pilot.send(visitor_post(START_LISTING, None, body)).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    assert!(text(&html).contains("We could not confirm whether your checkout started."), "{html}");
    let set: Vec<_> = headers.get_all(header::SET_COOKIE).iter().map(|v| v.to_str().unwrap().to_owned()).collect();
    assert!(set.iter().any(|c| c.starts_with("chase_sets_guest_checkout=gst_new;")), "{set:?}");
    let calls = pilot.stand.calls.lock().unwrap().clone();
    assert_eq!(calls.iter().filter(|c| c.path == "/api/auth/guest-checkout/start").count(), 1);
    let looked = calls.iter().find(|c| c.path.starts_with(CART_ATTEMPTS)).expect("one lookup");
    assert_eq!(looked.headers[header::COOKIE].to_str().unwrap(), "chase_sets_guest_checkout=gst_new", "as the new guest");

    // A visitor's refusal is the page's, with no second guest started.
    let body = "entryAttemptKey=chkentry_closed_00000000000000000";
    let (status, headers, html) = pilot.send(visitor_post(START_LISTING, None, body)).await;
    assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{html}");
    assert!(headers.get(header::SET_COOKIE).is_none(), "{headers:?}");
    assert_eq!(pilot.stand.calls.lock().unwrap().iter().filter(|c| c.path == "/api/auth/guest-checkout/start").count(), 2);
}

/// A request as a guest checkout's browser sends it: the guest checkout's cookie and no session.
fn as_guest(method: Method, uri: &str, body: &str) -> Request<Body> {
    Request::builder()
        .method(method)
        .uri(uri)
        .header(header::HOST, "localhost:7791")
        .header(header::COOKIE, "chase_sets_guest_checkout=gst_1")
        .header(header::CONTENT_TYPE, "application/x-www-form-urlencoded")
        .body(Body::from(body.to_owned()))
        .unwrap()
}

#[tokio::test]
async fn a_guest_checkout_is_the_pilots_page_with_every_step_a_form() {
    let pilot = Pilot::new().await;
    let (status, _, html) = pilot.send(as_guest(Method::GET, CHECKOUT_SCREEN, "")).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    let page = text(&html);
    assert!(page.contains("Enter contact, delivery, shipping, and payment details before secure payment starts."), "{page}");
    assert!(page.contains("Guest checkout contact and shipping details are used for this checkout"), "{page}");
    // The bar ends with Exit guest checkout, as marketplace's does.
    assert!(html.contains(r#"action="/guest-checkout/exit""#), "{html}");
    assert!(page.contains("Exit guest checkout"), "{page}");
    // No saved addresses or payment methods are read, and every step is a form.
    let calls = pilot.stand.calls.lock().unwrap().clone();
    assert!(!calls.iter().any(|c| c.path.contains("ship-from-addresses")), "no address book for a guest");
    assert!(!calls.iter().any(|c| c.path.contains("checkout-payment-affordances")), "no saved methods for a guest");
    assert!(html.contains(r#"data-step="delivery""#), "{html}");
    assert!(!html.contains("?edit=contact"), "a guest's contact is not opened again: {html}");
    // A saved payment method needs an account.
    let body = "intent=confirm-checkout&savedCheckoutInstrumentId=ins_1&shippingEmail=g%40example.test";
    let (status, _, html) = pilot.send(as_guest(Method::POST, CHECKOUT_SCREEN, body)).await;
    assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "{html}");
    assert!(text(&html).contains("Saved payment methods are available after sign-in."), "{html}");
    assert!(checkout_writes(&pilot).is_empty(), "nothing is written");
}

#[tokio::test]
async fn a_purchase_intent_is_the_pilots_page_and_submit_offer_shows_the_offer() {
    let pilot = Pilot::new().await;
    let (status, _, html) = pilot.send(get("/checkout/buy/session/chk_offer", Some("payer"))).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    let page = text(&html);
    assert!(page.contains("Confirm shipping details and submit an offer for sellers to review."), "{page}");
    assert!(page.contains("Delivery address is required so sellers know where the offer would ship if accepted."), "{page}");
    // The line at its offer, and No payment today: no shipping, tax, fee or wallet.
    assert!(page.contains("$24.50"), "{page}");
    assert!(page.contains("No payment today") && page.contains("Not applicable"), "{page}");
    assert!(page.contains("Sellers can accept your offer before an order and payment are created."), "{page}");
    assert!(page.contains("Shipping is saved for seller acceptance."), "{page}");
    for absent in ["Checkout service fee", "Payable total", "Pay now", "Totals need refresh", "Available balance"] {
        assert!(!page.contains(absent), "{absent}: {page}");
    }
    // Every step but payment is a form, and there is no payment step; the email is optional.
    assert!(html.contains(r#"data-step="delivery""#) && html.contains(r#"data-step="shipping""#), "{html}");
    assert!(!html.contains(r#"data-step="payment""#) && !html.contains("?edit="), "{html}");
    let email = &html[html.find(r#"type="email""#).unwrap()..];
    assert!(!email[..email.find('>').unwrap()].contains("required"), "{email}");
    assert!(html.contains(r#"data-commit="offer""#) && !html.contains(r#"data-commit="pay""#), "{html}");
    assert!(page.contains("Submit offer"), "{page}");
    // Nothing the page does not show is read.
    let calls = pilot.stand.calls.lock().unwrap().clone();
    for read in ["/api/settlement/wallet", "ship-from-addresses", "checkout-payment-affordances", "preview-status"] {
        assert!(!calls.iter().any(|c| c.path.contains(read)), "{read} was read");
    }

    // Submit offer confirms at once, even with the review changed (there are no totals to
    // refresh), without the authenticity check Checkout refuses a purchase intent, and goes to the
    // pilot's page for the offer, read after the write.
    let body = [
        "intent=confirm-checkout",
        "shippingAddressId=__manual",
        "shippingName=Demo+Collector",
        "shippingLine1=42+Binder+Lane",
        "shippingCity=Evanston",
        "shippingState=IL",
        "shippingPostalCode=60201",
        "shippingCountry=US",
        "shippingOption=standard",
        "reviewedShippingOption=priority",
        "paymentMethodCategory=card",
        "previewPaymentMethodCategory=card",
    ]
    .join("&");
    let (status, headers, html) = pilot.send(post("/checkout/buy/session/chk_offer", "payer", &body, false)).await;
    assert_eq!(status, StatusCode::SEE_OTHER, "{html}");
    let to = headers[header::LOCATION].to_str().unwrap();
    assert!(to.starts_with("/account/offers/submitted/ofr_1?after_write="), "{to}");
    let writes: Vec<String> = checkout_writes(&pilot).into_iter().map(|(write, _)| write).collect();
    assert_eq!(writes, ["shipping-option", "confirm"], "{writes:?}");
    let (_, confirm) = checkout_writes(&pilot).pop().unwrap();
    assert_eq!(confirm["shippingAddress"]["line1"], "42 Binder Lane", "{confirm}");

    // A session whose offer was submitted is the offer's page.
    let (status, headers, _) = pilot.send(get("/checkout/buy/session/chk_offered", Some("payer"))).await;
    assert_eq!((status, headers[header::LOCATION].to_str().unwrap()), (StatusCode::SEE_OTHER, "/account/offers/submitted/ofr_1"));
}

#[tokio::test]
async fn a_guest_payment_is_the_pilots_page_with_retry_and_save() {
    let pilot = Pilot::new().await;
    // Waiting for the guest: Stripe's step and the watch, read at the guest's address, and no
    // account links.
    let (status, _, html) = pilot.send(as_guest(Method::GET, "/checkout/payments/pay_1", "")).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    assert!(html.contains("/checkout/payments/pay_1/status?since=pending-confirmation&amp;until="), "{html}");
    assert!(!html.contains(r#"href="/account/purchases""#), "no Back to purchases: {html}");
    assert!(!html.contains(r#"href="/account/purchases/ord_pay""#), "no Open purchase: {html}");
    let until = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs() + 60;
    let mut part =
        as_guest(Method::GET, &format!("/checkout/payments/pay_1/status?since=pending-confirmation&until={until}"), "");
    part.headers_mut().insert("corten", "action".parse().unwrap());
    let (status, _, html) = pilot.send(part).await;
    assert_eq!(status, StatusCode::OK, "{html}");
    assert!(html.contains(r#"data-from="/checkout/payments/pay_1/status?since=pending-confirmation"#), "{html}");

    // A failed payment: Retry payment is a form; it asks Payments for the orders' quote again and
    // a new payment at it, then goes to the new payment, read after it.
    let (_, _, html) = pilot.send(as_guest(Method::GET, "/checkout/payments/pay_failed", "")).await;
    assert!(html.contains(r#"action="/checkout/payments/pay_failed""#) && html.contains(r#"value="retry-payment""#), "{html}");
    assert!(!html.contains("/account/payments/new"), "{html}");
    let (status, headers, html) =
        pilot.send(as_guest(Method::POST, "/checkout/payments/pay_failed", "intent=retry-payment")).await;
    assert_eq!(status, StatusCode::SEE_OTHER, "{html}");
    assert!(headers[header::LOCATION].to_str().unwrap().starts_with("/checkout/payments/pay_retry?afterWrite="), "{headers:?}");
    let calls = pilot.stand.calls.lock().unwrap().clone();
    let quoted = calls.iter().find(|c| c.path.starts_with("/api/marketplace/account/checkout/status")).unwrap();
    assert!(
        quoted.path.contains("orderIds=ord_pay") && quoted.path.contains("requestedBalanceCreditAmount=25.00"),
        "{}",
        quoted.path
    );
    let recover = calls.iter().find(|c| c.path == "/api/marketplace/account/checkout/recover").unwrap();
    let sent: Value = serde_json::from_str(&recover.body).unwrap();
    assert_eq!(sent["marketplaceCheckoutFeeQuoteFingerprint"], "fp-retry");
    assert_eq!(sent["returnUrlPath"], "/checkout/payments/:paymentId");
    assert_eq!(sent["orderIds"], json!(["ord_pay"]));
    assert_eq!(sent["paymentMethodCategory"], "card");
    // A payment that is still open cannot be retried.
    let (status, _, html) = pilot.send(as_guest(Method::POST, "/checkout/payments/pay_1", "intent=retry-payment")).await;
    assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "{html}");
    assert!(text(&html).contains("This payment cannot be retried."), "{html}");

    // Paid: Save this order, marketplace's page at the same address.
    let (_, _, html) = pilot.send(as_guest(Method::GET, "/checkout/payments/pay_paid", "")).await;
    assert!(text(&html).contains("Save this order"), "{html}");
    assert!(html.contains(r#"href="http://localhost:7753/checkout/payments/pay_paid""#), "{html}");
    // A claim link's landing goes on to marketplace's page with it.
    let (status, headers, _) = pilot.send(as_guest(Method::GET, "/checkout/payments/pay_paid?claimContinuation=cc_1", "")).await;
    assert_eq!(
        (status, headers[header::LOCATION].to_str().unwrap()),
        (StatusCode::SEE_OTHER, "http://localhost:7753/checkout/payments/pay_paid?claimContinuation=cc_1")
    );

    // An account goes to its own payment page; no guest checkout, or one Payments refuses, is told
    // the link is no longer good.
    let (status, headers, _) = pilot.send(get("/checkout/payments/pay_1", Some("payer"))).await;
    assert_eq!((status, headers[header::LOCATION].to_str().unwrap()), (StatusCode::SEE_OTHER, "/account/payments/pay_1"));
    let (status, _, html) = pilot.send(get("/checkout/payments/pay_1", None)).await;
    assert_eq!(status, StatusCode::UNAUTHORIZED, "{html}");
    assert!(text(&html).contains("This guest checkout payment link is invalid or expired."), "{html}");
    let (status, _, html) = pilot.send(as_guest(Method::GET, "/checkout/payments/pay_gone", "")).await;
    assert_eq!(status, StatusCode::UNAUTHORIZED, "{html}");
}

